<script setup lang="ts">
import { computed, inject, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { routerKey } from 'vue-router'
import { ApiError, LatestRequest, useApi } from '../../api/client'
import { replyLabels, type Direction, type Letter, type LetterOptions, type MaterialOption, type ReplyCompleteness, type WorkOption } from '../../api/letters'
import type { Page } from '../../api/types'
import { useSessionStore } from '../../stores/session'
import ApiMessage from '../../shared/ui/ApiMessage.vue'
import { useDirtyGuard } from '../../shared/ui/useDirtyGuard'
import { useLetterAttempt } from './useLetterAttempt'
const props = defineProps<{ options: LetterOptions; letter?: Letter; initialDirection?: Direction; parentId?: string; expertiseId?: string }>()
const emit = defineEmits<{ updated: [letter: Letter]; cancel: [] }>()
const api = useApi(), session = useSessionStore(), workRequests = new LatestRequest(), materialRequests = new LatestRequest(), parentRequests = new LatestRequest()
const source = props.letter?.content
const baseVersion = ref(props.letter?.version)
const direction = ref<Direction>(props.letter?.direction ?? props.initialDirection ?? 'incoming'), department = ref(props.letter?.department?.id ?? '')
const fields = reactive({ kind_id: source?.kind?.id ?? '', subject: source?.subject ?? '', body: source?.body ?? '', sender_name: source?.sender_name ?? '', external_number: source?.external_number ?? '', external_on: source?.external_on ?? '', document_on: source?.document_on ?? '', received_on: source?.received_on ?? '', note: source?.note ?? '', material_id: source?.material?.id ?? '', expertise_ids: source?.expertises.map(item => item.id) ?? (props.expertiseId ? [props.expertiseId] : []), reply_completeness: source?.reply_completeness ?? '' as ReplyCompleteness | '', recipients: source?.recipients.map(({ name, address, email }) => ({ name, address, email })) ?? [], reason: '' })
const normalized = computed(() => ({ kind_id: fields.kind_id || null, subject: fields.subject.trim(), body: fields.body.trim(), sender_name: fields.sender_name.trim(), external_number: fields.external_number.trim(), external_on: fields.external_on || null, document_on: fields.document_on || null, received_on: fields.received_on || null, note: fields.note.trim(), material_id: fields.material_id || null, expertise_ids: [...fields.expertise_ids].sort(), reply_completeness: fields.reply_completeness || null, recipients: fields.recipients.map(item => ({ name: item.name.trim(), address: item.address.trim(), email: item.email.trim() })) }))
const stamp = computed(() => JSON.stringify({ ...normalized.value, direction: direction.value, department_id: department.value || null, parent_id: props.parentId || null, reason: fields.reason.trim() }))
const initial = stamp.value, saved = ref(false)
const { attempt, busy, error, recovering, reset, execute } = useLetterAttempt(stamp)
const authorized = computed(() => props.letter ? props.letter.allowed_actions.includes('letters.draft') : session.can('letters.draft') && (!props.parentId || session.can('letters.reply')))
const dirty = computed(() => !saved.value && (stamp.value !== initial || Boolean(attempt.value)))
const confirmLeave = useDirtyGuard(() => dirty.value || busy.value, inject(routerKey, undefined))
const conflict = computed(() => error.value instanceof ApiError && error.value.status === 409 && attempt.value && props.letter && attempt.value.body.expected_version !== props.letter.version)
const works = ref<WorkOption[]>([]), materials = ref<MaterialOption[]>([]), workSearch = ref(''), materialSearch = ref(''), optionsError = ref<unknown>(null), parent = ref<Letter | null>(null)
const selectedWorks = computed(() => fields.expertise_ids.map(id => works.value.find(item => item.id === id) ?? { id, registration_number: source?.expertises.find(item => item.id === id)?.registration_number ?? id, material: { id: '', title: '' } }))
async function loadWorks() { try { await workRequests.run(signal => api.request<Page<WorkOption>>(`/letters/work-options/?${new URLSearchParams({ search: workSearch.value.trim() })}`, { signal }), value => { works.value = value.results }) } catch (cause) { optionsError.value = cause } }
async function loadMaterials() { try { await materialRequests.run(signal => api.request<Page<MaterialOption>>(`/letters/material-options/?${new URLSearchParams({ search: materialSearch.value.trim() })}`, { signal }), value => { materials.value = value.results }) } catch (cause) { optionsError.value = cause } }
async function loadParent() { if (props.parentId) { try { await parentRequests.run(signal => api.request<Letter>(`/letters/${props.parentId}/`, { signal }), value => { parent.value = value; direction.value = value.direction === 'incoming' ? 'outgoing' : 'incoming' }) } catch (cause) { optionsError.value = cause } } }
function cancel() { if (!busy.value && confirmLeave()) emit('cancel') }
function acceptVersion() { baseVersion.value = props.letter?.version; reset() }
async function save() {
  if ((!authorized.value && !recovering.value) || (!fields.reason.trim() && !recovering.value)) return
  const result = await execute(props.letter ? `/letters/${props.letter.id}/draft/` : '/letters/', async () => props.letter
    ? { ...normalized.value, expected_version: baseVersion.value, reason: fields.reason.trim() }
    : { direction: direction.value, department_id: department.value || null, parent_id: props.parentId || null, ...normalized.value, reason: fields.reason.trim() })
  if (result) { saved.value = true; reset(); fields.reason = ''; emit('updated', result.letter) }
}
onMounted(() => { void loadWorks(); void loadMaterials(); void loadParent() })
onBeforeUnmount(() => { workRequests.cancel(); materialRequests.cancel(); parentRequests.cancel() })
</script>
<template>
  <form data-letter-draft class="form-grid" @submit.prevent="save"><div class="section-heading"><h2>{{ letter ? 'Новая редакция черновика' : parentId ? 'Черновик ответа' : 'Новое письмо' }}</h2><span v-if="dirty" class="badge badge-amber">Есть изменения</span></div><ApiMessage :error="error" /><ApiMessage :error="optionsError" />
    <p v-if="recovering" class="message">Ответ не получен. Повтор сохранит исходное содержание, версию и ключ.</p><p v-else-if="!authorized" class="message message-error">Сохранение больше не разрешено. Данные остались в форме.</p><p v-if="conflict" class="message">Сведения обновлены, черновик сохранён в форме. Сравните его с серверными сведениями выше: новая попытка сохранит содержание из формы. <button type="button" data-accept-draft-version :disabled="busy || !authorized" @click="acceptVersion">Применить версию {{ letter?.version }} к новой попытке</button></p>
    <p v-if="parentId" class="muted">Ответ на {{ parent?.registration?.registration_number || parent?.content.subject || 'выбранное письмо' }}. Связь задаётся при создании.</p>
    <fieldset class="form-grid" :disabled="busy || (!authorized && !recovering)">
      <div class="form-columns"><label v-if="!letter">Направление<select v-model="direction" name="direction" :disabled="Boolean(parentId)"><option value="incoming">Входящее</option><option value="outgoing">Исходящее</option></select></label><label v-if="!letter">Отдел<select v-model="department" name="department_id"><option value="">Не указан / самостоятельное письмо</option><option v-for="item in options.departments.filter(item => item.is_active)" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>Вид письма<select v-model="fields.kind_id" name="kind_id"><option value="">Пока не определён</option><option v-for="item in options.kinds.filter(item => item.is_active || item.id === source?.kind?.id)" :key="item.id" :value="item.id">{{ item.name }}{{ item.is_active ? '' : ' (неактивен)' }}</option></select></label></div>
      <label>Тема<input v-model="fields.subject" name="subject" /></label><label>Содержание<textarea v-model="fields.body" name="body" rows="6" /></label><label v-if="direction === 'incoming'">Отправитель<input v-model="fields.sender_name" name="sender_name" /></label>
      <div class="form-columns"><label>Внешний номер<input v-model="fields.external_number" name="external_number" /></label><label>Внешняя дата<input v-model="fields.external_on" name="external_on" type="date" /></label><label>Дата документа<input v-model="fields.document_on" name="document_on" type="date" /></label><label v-if="direction === 'incoming'">Фактическое получение, если известно<input v-model="fields.received_on" name="received_on" type="date" /></label></div>
      <fieldset><legend>Адресаты</legend><div v-for="(item, index) in fields.recipients" :key="index" class="inset-form form-grid"><label>Наименование<input v-model="item.name" :name="`recipient_name_${index}`" /></label><label>Адрес<input v-model="item.address" :name="`recipient_address_${index}`" /></label><label>Email, если известен<input v-model="item.email" :name="`recipient_email_${index}`" type="email" /></label><button type="button" @click="fields.recipients.splice(index, 1)">Убрать адресата</button></div><button type="button" data-add-recipient @click="fields.recipients.push({ name: '', address: '', email: '' })">Добавить адресата</button></fieldset>
      <label v-if="parentId || source?.parent">Полнота ответа<select v-model="fields.reply_completeness" name="reply_completeness"><option value="">Пока не определена</option><option v-for="(label, value) in replyLabels" :key="value" :value="value">{{ label }}</option></select></label>
      <fieldset class="form-grid"><legend>Связанные работы</legend><div class="button-row"><label>Поиск доступных работ<input v-model="workSearch" name="work_search" type="search" /></label><button type="button" @click="loadWorks">Найти работы</button></div><label v-for="item in works" :key="item.id" class="check-label"><input v-model="fields.expertise_ids" name="expertise_ids" type="checkbox" :value="item.id" />{{ item.registration_number }} · {{ item.material.title }}</label><p class="muted compact">Выбрано: {{ selectedWorks.map(item => item.registration_number).join(', ') || 'самостоятельное письмо' }}</p><button v-for="item in selectedWorks" :key="item.id" type="button" @click="fields.expertise_ids = fields.expertise_ids.filter(id => id !== item.id)">Убрать {{ item.registration_number }}</button></fieldset>
      <fieldset class="form-grid"><legend>Материал</legend><div class="button-row"><label>Поиск доступного материала<input v-model="materialSearch" name="material_search" type="search" /></label><button type="button" @click="loadMaterials">Найти материал</button></div><label>Связанный материал<select v-model="fields.material_id" name="material_id"><option value="">Не связан</option><option v-if="fields.material_id && !materials.some(item => item.id === fields.material_id)" :value="fields.material_id">{{ source?.material?.title || fields.material_id }}</option><option v-for="item in materials" :key="item.id" :value="item.id">{{ item.title || item.id }}</option></select></label></fieldset>
      <label>Примечание<textarea v-model="fields.note" name="note" /></label><label>Причина / основание редакции<textarea v-model="fields.reason" name="draft_reason" required /></label>
    </fieldset><p class="muted compact">Черновик допускает неполные сведения. Неизвестные даты сохранятся пустыми; регистрация выполняется отдельным действием.</p><div class="button-row"><button type="submit" class="button-primary" :formnovalidate="recovering" :disabled="busy || ((!authorized || !fields.reason.trim()) && !recovering)">{{ busy ? 'Сохранение…' : recovering ? 'Повторить ту же попытку' : 'Сохранить черновик' }}</button><button type="button" :disabled="busy" @click="cancel">Отмена</button></div>
  </form>
</template>
